\set ON_ERROR_STOP on
set timezone='UTC';
create schema message_send_test;
create function message_send_test.id(n integer) returns uuid language sql immutable as $$select ('99950000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create table message_send_test.workspace(value jsonb);
create table message_send_test.cases(name text primary key,request jsonb,response jsonb);
grant usage on schema message_send_test to authenticated;
grant select,insert on all tables in schema message_send_test to authenticated;
insert into auth.users(id,email) select message_send_test.id(n),'message-send-'||n||'@example.test' from generate_series(1,2)n;
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
set role authenticated;
insert into message_send_test.workspace select public.mobile_create_team_workspace(jsonb_build_object('version',2,'userId',auth.uid(),'requestNonce',message_send_test.id(10),'value',jsonb_build_object('name','Message Team','code','MS-12345','location','Church','callTime','09:00:00','rehearsalTime','08:00:00')))->'workspace';
reset role;
create function message_send_test.channel() returns uuid language sql stable as $$select(value->>'channelId')::uuid from message_send_test.workspace$$;
create function message_send_test.member() returns uuid language sql stable as $$select(value->>'memberId')::uuid from message_send_test.workspace$$;
create function message_send_test.capture(label text,n integer,body text) returns void language plpgsql as $$declare proof record;request jsonb;begin
 select * into proof from public.send_message_once(message_send_test.channel(),message_send_test.id(n),body);
 select jsonb_build_object('version',2,'userId',auth.uid(),'teamId',tm.team_id,'memberId',tm.id,'memberCreatedAt',tm.created_at,'channelId',message_send_test.channel(),'requestNonce',message_send_test.id(n),'body',body) into request from public.team_members tm where tm.id=message_send_test.member();
 insert into message_send_test.cases values(label,request,jsonb_build_object('version',2,'request',request,'status','confirmed','message',jsonb_build_object('id',proof.id,'createdAt',proof.created_at)));
end$$;
create function message_send_test.denied(channel uuid,n integer,body text,expected text) returns void language plpgsql as $$declare rejected boolean:=false;begin begin perform public.send_message_once(channel,message_send_test.id(n),body);exception when others then if sqlstate=expected then rejected:=true;else raise;end if;end;assert rejected,'Expected denied message send';end$$;
insert into auth.users(id,email) values(message_send_test.id(3),'direct-third@example.test');
insert into public.team_members(id,team_id,profile_id,role,status) select message_send_test.id(n+10),(value->>'teamId')::uuid,message_send_test.id(n),'member','active' from message_send_test.workspace cross join generate_series(2,3)n;
update public.team_members set role='worship_leader' where id=message_send_test.id(12);
select set_config('request.jwt.claim.sub','',false);
insert into public.songs(id,team_id,title,artist,original_key,bpm,lyrics_chords,created_by,created_at,deleted_at) select message_send_test.id(1000+n),(value->>'teamId')::uuid,'Trashed song '||n,'Actual artist','C',100,'Preserved lyrics',message_send_test.id(1),'2026-10-24T03:04:05.123456Z','2026-10-24T04:05:06.654321Z' from message_send_test.workspace cross join generate_series(0,51)n;
insert into public.songs(id,team_id,title,artist,original_key,bpm,lyrics_chords,status,created_by,deleted_at) select message_send_test.id(2000),(value->>'teamId')::uuid,'Pending hidden','Actual artist','C',100,'Hidden lyrics','pending',message_send_test.id(1),clock_timestamp() from message_send_test.workspace;
create schema song_restore_test;
create table song_restore_test.cases(name text primary key,request jsonb not null,receipt jsonb not null);
create table song_restore_test.pending(name text primary key,request jsonb not null);
grant usage on schema song_restore_test to authenticated;
grant select,insert on all tables in schema song_restore_test to authenticated;
create function song_restore_test.team() returns uuid language sql stable as $$select(value->>'teamId')::uuid from message_send_test.workspace$$;
create function song_restore_test.request(n integer,song integer default 1000) returns jsonb language sql stable as $$select jsonb_build_object('version',2,'userId',auth.uid(),'teamId',tm.team_id,'memberId',tm.id,'memberCreatedAt',tm.created_at,'requestNonce',message_send_test.id(n),'base',private.mobile_song_restore_snapshot(s)) from public.team_members tm join public.songs s on s.team_id=tm.team_id and s.id=message_send_test.id(song) where tm.profile_id=auth.uid() and tm.team_id=song_restore_test.team()$$;
-- Request construction is fixture-only; authenticated callers receive the same
-- base through the public approved-only state RPC, not private helper access.
alter function song_restore_test.request(integer,integer) security definer;
create function song_restore_test.capture(label text,request jsonb) returns jsonb language plpgsql as $$declare receipt jsonb;begin receipt:=public.mobile_restore_song(request);insert into song_restore_test.cases values(label,request,receipt);return receipt;end$$;
create function song_restore_test.denied(request jsonb,expected text) returns void language plpgsql as $$declare rejected boolean:=false;begin begin perform public.mobile_restore_song(request);exception when others then if sqlstate=expected then rejected:=true;else raise;end if;end;assert rejected,'Expected song restore denial';end$$;
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
set role authenticated;
do $$declare page jsonb;begin page:=public.mobile_read_song_trash(song_restore_test.team(),message_send_test.member(),null);assert jsonb_array_length(page->'items')=50 and page->>'nextCursor'=message_send_test.id(1049)::text,'Trash pagination incorrect';assert(page#>>'{0,snapshot,id}') is null;assert(public.mobile_read_song_restore_state(song_restore_test.team(),message_send_test.member(),message_send_test.id(2000))->'current')='null'::jsonb,'Pending song exposed';end$$;
insert into song_restore_test.pending values('original',song_restore_test.request(100));
select song_restore_test.capture('applied',(select request from song_restore_test.pending where name='original'));
do $$declare saved record;begin select * into saved from song_restore_test.cases where name='applied';assert public.mobile_restore_song(saved.request)=saved.receipt,'Retry receipt changed';assert exists(select 1 from public.songs where id=message_send_test.id(1000) and deleted_at is null and sync_revision=2 and lyrics_chords='Preserved lyrics'),'Restore changed content or revision';assert not exists(select 1 from public.mobile_deleted_records where team_id=song_restore_test.team() and entity_type='song' and entity_id=message_send_test.id(1000)),'Restore tombstone retained';assert exists(select 1 from public.worship_sync_changes where entity_id=message_send_test.id(1000) and revision=2 and operation='upsert'),'Restore sync upsert missing';end$$;
select song_restore_test.denied(jsonb_set((select request from song_restore_test.pending where name='original'),'{base,revision}','99'),'22023');
select song_restore_test.denied(jsonb_set(song_restore_test.request(101,1001),'{memberCreatedAt}','"2026-10-24T01:00:00Z"'),'42501');
select song_restore_test.denied(jsonb_set(song_restore_test.request(101,1001),'{base,teamId}',to_jsonb(message_send_test.id(9998))),'42501');
insert into song_restore_test.pending values('stale-revision',song_restore_test.request(102,1001)),('stale-delete',song_restore_test.request(103,1002)),('replacement',song_restore_test.request(104,1003));
reset role;
select set_config('request.jwt.claim.sub','',false);
update public.songs set title='Newer trashed title' where id=message_send_test.id(1001);
update public.songs set deleted_at='2026-10-24T05:00:00Z' where id=message_send_test.id(1002);
delete from public.songs where id=message_send_test.id(1003);
insert into public.songs(id,team_id,title,artist,original_key,bpm,lyrics_chords,created_by,created_at,deleted_at) values(message_send_test.id(1003),song_restore_test.team(),'Replacement','Artist','C',100,'Replacement lyrics',message_send_test.id(1),'2026-10-24T06:00:00Z','2026-10-24T04:05:06.654321Z');
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
set role authenticated;
select song_restore_test.capture('revision-conflict',(select request from song_restore_test.pending where name='stale-revision'));
select song_restore_test.capture('deletion-conflict',(select request from song_restore_test.pending where name='stale-delete'));
select song_restore_test.capture('incarnation-conflict',(select request from song_restore_test.pending where name='replacement'));
select song_restore_test.capture('missing',jsonb_set(song_restore_test.request(105,1004),'{base,id}',to_jsonb(message_send_test.id(9999))));
reset role;
-- Current worship-leader deletion authority works without general editor power.
select set_config('request.jwt.claim.sub',message_send_test.id(2)::text,false);
set role authenticated;
select song_restore_test.capture('worship-leader',song_restore_test.request(106,1005));
reset role;
insert into public.team_permission_overrides(team_id,member_id,permission,allowed) values(song_restore_test.team(),message_send_test.id(12),'songs.edit',false);
set role authenticated;
select song_restore_test.denied((select request from song_restore_test.cases where name='worship-leader'),'42501');
reset role;
delete from public.team_permission_overrides where member_id=message_send_test.id(12);
select set_config('request.jwt.claim.sub','',false);
delete from public.team_members where id=message_send_test.id(12);
insert into public.team_members(id,team_id,profile_id,role,status,created_at) values(message_send_test.id(12),song_restore_test.team(),message_send_test.id(2),'worship_leader','active','2026-10-24T07:00:00Z');
select set_config('request.jwt.claim.sub',message_send_test.id(2)::text,false);
set role authenticated;
select song_restore_test.denied((select request from song_restore_test.cases where name='worship-leader'),'42501');
reset role;
select set_config('request.jwt.claim.sub',message_send_test.id(3)::text,false);
set role authenticated;
select song_restore_test.denied(song_restore_test.request(107,1006),'42501');
select song_restore_test.denied((select request from song_restore_test.pending where name='original'),'42501');
reset role;
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
create function song_restore_test.fail_late() returns trigger language plpgsql as $$begin if new.request_nonce=message_send_test.id(108) then raise exception 'Synthetic restore ledger failure';end if;return new;end$$;
create trigger song_restore_late before insert on private.mobile_song_restore_receipts for each row execute function song_restore_test.fail_late();
create table song_restore_test.before_rollback as select to_jsonb(s) song,(select count(*) from public.worship_sync_changes where entity_id=s.id) changes,(select to_jsonb(d) from public.mobile_deleted_records d where team_id=s.team_id and entity_id=s.id and entity_type='song') tombstone from public.songs s where id=message_send_test.id(1006);
set role authenticated;
select song_restore_test.denied(song_restore_test.request(108,1006),'P0001');
reset role;
do $$begin assert(select b.song=to_jsonb(s) and b.changes=(select count(*) from public.worship_sync_changes where entity_id=s.id) and b.tombstone=(select to_jsonb(d) from public.mobile_deleted_records d where team_id=s.team_id and entity_id=s.id and entity_type='song') from song_restore_test.before_rollback b cross join public.songs s where s.id=message_send_test.id(1006)),'Late restore failure changed song/revision/sync/tombstone';end$$;
drop trigger song_restore_late on private.mobile_song_restore_receipts;
-- Original history cannot restore a later deletion or physical replacement.
update public.songs set deleted_at=clock_timestamp() where id=message_send_test.id(1000);
set role authenticated;
do $$declare saved record;begin select * into saved from song_restore_test.cases where name='applied';assert public.mobile_restore_song(saved.request)=saved.receipt;assert exists(select 1 from public.songs where id=message_send_test.id(1000) and deleted_at is not null and sync_revision=3),'History revived later deletion';end$$;
reset role;
select set_config('request.jwt.claim.sub','',false);
delete from public.songs where id=message_send_test.id(1000);
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
set role authenticated;
do $$declare saved record;begin select * into saved from song_restore_test.cases where name='applied';assert public.mobile_restore_song(saved.request)=saved.receipt;assert not exists(select 1 from public.songs where id=message_send_test.id(1000)),'History recreated purged song';end$$;
reset role;

